### Testing Guards

```typescript
describe('AuthGuard', () => {
  let authService: jasmine.SpyObj<Auth>;

  beforeEach(() => {
    authService = jasmine.createSpyObj('Auth', ['isAuthenticated']);

    TestBed.configureTestingModule({
      providers: [
        { provide: Auth, useValue: authService },
        provideRouter([
          { path: 'login', component: Login },
          {
            path: 'dashboard',
            component: Dashboard,
            canActivate: [authGuard],
          },
        ]),
      ],
    });
